import { test } from "node:test";
import assert from "node:assert/strict";
import { clamp } from "./clamp.mjs";

test("inside range", () => { assert.equal(clamp(5, 0, 10), 5); });

test("below range", () => { assert.equal(clamp(-3, 0, 10), 0); });

test("above range", () => { assert.equal(clamp(15, 0, 10), 10); });

test("equal to low", () => { assert.equal(clamp(0, 0, 10), 0); });

test("equal to high", () => { assert.equal(clamp(10, 0, 10), 10); });
